import { geolocateEuropeanCapitalFallback } from './worldMicroEventGeography';

/**
 * Worldwide news microevents, 2023 – August 2026.
 *
 * The migration microevents in `migrationEntryNodes.ts` are pinned to street-level facilities and
 * only reveal at city zoom. This set is the planetary counterpart: individual reported events
 * across six themes, spread over every inhabited continent, revealed at mid zoom so the globe
 * reads as a month-by-month record of the year rather than a single theatre.
 *
 * ## Provenance — read before adding a record
 *
 * Every record is a *reported* event with a date and a source. Nothing here is inferred,
 * extrapolated or invented. The bulk are taken from Wikipedia's `Portal:Current events` day
 * pages, which is why `url` usually points at a dated portal page rather than an outlet: the day
 * page carries the event's own citations and stays reachable, where an outlet URL rots. A handful
 * of cybersecurity records cite the trade press directly because no portal entry covers them.
 *
 * ## Coordinates are not all the same thing
 *
 * `precision` is load-bearing and must be set honestly, the same way `warOrderOfBattle.ts` marks
 * its sector anchors:
 *
 *  - `city`     — the event happened at this settlement or installation. Good to a few km.
 *  - `area`     — a province, border region, or stretch of sea. The coordinate is a centroid and
 *                 says "somewhere in here", never a location.
 *  - `national` — a policy, ruling, election or corporate action with no single site. Imported
 *                 records may use an administrative anchor; named European places are corrected
 *                 through `worldMicroEventGeography.ts` before the map receives them.
 *
 * The hover card prints the precision for `area` and `national` records, so a centroid can never
 * be read off the globe as a place where something occurred.
 */

export const WORLD_MICROEVENT_CATEGORIES = [
  'war',
  'trade',
  'cyber',
  'tech',
  'politics',
  'migration',
  'disaster',
] as const;

export type WorldMicroEventCategory = (typeof WORLD_MICROEVENT_CATEGORIES)[number];

export type WorldMicroEventPrecision = 'city' | 'area' | 'national';

export interface WorldMicroEvent {
  id: string;
  /** ISO date the event was reported for. */
  date: string;
  category: WorldMicroEventCategory;
  headline: string;
  /** Place as reported, shown on the hover card. */
  place: string;
  /** `[longitude, latitude]`, GeoJSON order. */
  coordinate: readonly [number, number];
  precision: WorldMicroEventPrecision;
  /** One sentence on what was reported. */
  summary: string;
  /** Publisher of the record cited in `url`. */
  source: string;
  url: string;
}

/** Presentation for each theme: dot colour, four-letter pin code, and the hover-card label. */
export const WORLD_MICROEVENT_CATEGORY_META: Record<
  WorldMicroEventCategory,
  { label: string; code: string; color: string }
> = {
  war: { label: 'Armed conflict', code: 'WAR', color: '#e0483b' },
  trade: { label: 'Trade & shipping', code: 'TRD', color: '#2fd4bf' },
  cyber: { label: 'Cyber & information', code: 'CYB', color: '#a97bff' },
  tech: { label: 'Technology', code: 'TCH', color: '#4ea8ff' },
  politics: { label: 'Politics & government', code: 'POL', color: '#d8c24a' },
  migration: { label: 'Migration', code: 'MIG', color: '#ff8f5e' },
  disaster: { label: 'Disaster & hazard', code: 'DIS', color: '#7fb069' },
};

/** Human-readable precision caveat, or `''` for a `city` record that needs none. */
export const WORLD_MICROEVENT_PRECISION_LABEL: Record<WorldMicroEventPrecision, string> = {
  city: '',
  area: 'Area centroid — regional, not a location',
  national: 'National-level record — plotted at the capital',
};

/** Wikipedia current-events day page for a 2026 date, which carries the entry's own citations. */
const portal = (month: string, day: number) =>
  `https://en.wikipedia.org/wiki/Portal:Current_events/2026_${month}_${day}`;

const WIKI = 'Wikipedia · Current events';

