/**
 * Render-ready records. European imports that named a real settlement or region but carried a
 * country-capital fallback are resolved here, at the data boundary, so every map consumer gets
 * the corrected coordinates and precision.
 */
export const WORLD_MICROEVENTS: readonly WorldMicroEvent[] = RAW_WORLD_MICROEVENTS.map(
  geolocateEuropeanCapitalFallback,
);

/** Events newest first — the order the ticker and any list view should read in. */
export const WORLD_MICROEVENTS_BY_DATE: readonly WorldMicroEvent[] = [...WORLD_MICROEVENTS].sort(
  (a, b) => b.date.localeCompare(a.date),
);

/** Count per theme, for the legend. */
export function worldMicroEventCounts(): Record<WorldMicroEventCategory, number> {
  const counts = Object.fromEntries(
    WORLD_MICROEVENT_CATEGORIES.map((category) => [category, 0]),
  ) as Record<WorldMicroEventCategory, number>;
  for (const event of WORLD_MICROEVENTS) counts[event.category] += 1;
  return counts;
}
